-- Initial Quizette schema.
--
-- Conventions used throughout:
--   * IDs are UUIDv7 generated by the application (IDGenerator port), so rows have an
--     identity before they are saved and new rows sort by creation time in indexes.
--   * Status-like columns are `text NOT NULL CHECK (col IN (...))` instead of Postgres
--     ENUM types. Adding a value to an ENUM needs ALTER TYPE, which can't run inside a
--     transaction on older Postgres versions and can't remove values at all; changing a
--     CHECK constraint is an ordinary, transactional migration. The allowed values mirror
--     the Go constants in internal/domain.
--   * Every table hangs off users with ON DELETE CASCADE, so deleting a topic or chapter
--     removes everything generated from it (questions, jobs, attempts, answers).
--   * IF NOT EXISTS keeps the migration safe to re-run against a partially created
--     database (for example, after a failed first deploy).

-- +goose Up
CREATE EXTENSION IF NOT EXISTS citext; -- case-insensitive text for emails and topic names

CREATE TABLE IF NOT EXISTS users (
    id            uuid PRIMARY KEY,
    email         citext NOT NULL UNIQUE,       -- citext: Ada@x.com and ada@x.com are the same account
    password_hash text,                         -- NULL for users who only sign in with OAuth
    name          text NOT NULL,
    avatar_url    text NOT NULL DEFAULT '',
    created_at    timestamptz NOT NULL
);

-- One user can link several providers (Google and GitHub); each provider account maps to one user.
CREATE TABLE IF NOT EXISTS oauth_accounts (
    user_id          uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    provider         text NOT NULL,             -- 'google' | 'github'
    provider_user_id text NOT NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (provider, provider_user_id)
);
CREATE INDEX IF NOT EXISTS oauth_accounts_user_idx ON oauth_accounts (user_id);

-- Only the SHA-256 of the session token is stored, so a database leak doesn't expose
-- usable session cookies.
CREATE TABLE IF NOT EXISTS sessions (
    token_hash text PRIMARY KEY,
    user_id    uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions (user_id);
CREATE INDEX IF NOT EXISTS sessions_expires_idx ON sessions (expires_at); -- hourly purge of expired sessions

-- A user's named group of chapters. The UNIQUE constraint enforces the Topic invariant
-- "names are unique per user" (case-insensitively, via citext).
CREATE TABLE IF NOT EXISTS topics (
    id         uuid PRIMARY KEY,
    owner_id   uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name       citext NOT NULL,
    created_at timestamptz NOT NULL,
    UNIQUE (owner_id, name)
);

-- One uploaded PDF. owner_id is denormalised from the topic so every query can filter
-- by owner without a join; that is how ownership is enforced.
CREATE TABLE IF NOT EXISTS chapters (
    id         uuid PRIMARY KEY,
    topic_id   uuid NOT NULL REFERENCES topics (id) ON DELETE CASCADE,
    owner_id   uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    title      text NOT NULL,
    -- domain.ChapterStatus: pending while generating, then ready or failed.
    status     text NOT NULL CHECK (status IN ('pending', 'ready', 'failed')),
    created_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS chapters_owner_topic_idx ON chapters (owner_id, topic_id, created_at);

-- One attempt to turn a PDF into a question set. Documents are never stored: only their
-- metadata is kept, and there is deliberately no bytes column (ADR 0003; a test checks this).
-- The metric columns record cost and latency for the pdf-native vs text-extract experiment.
CREATE TABLE IF NOT EXISTS processing_jobs (
    id                 uuid PRIMARY KEY,
    chapter_id         uuid NOT NULL REFERENCES chapters (id) ON DELETE CASCADE,
    owner_id           uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    -- domain.QuestionSpec: 5 to 30 questions, in steps of 5.
    requested_count    int NOT NULL CHECK (requested_count BETWEEN 5 AND 30 AND requested_count % 5 = 0),
    type_mix           text[] NOT NULL,         -- question types requested, e.g. {mcq,true_false,mrq}
    doc_filename       text NOT NULL,
    doc_size           bigint NOT NULL,         -- bytes
    doc_sha256         text NOT NULL,           -- hex; allows future de-duplication without keeping the file
    -- domain.JobStatus state machine: queued -> running -> succeeded | failed.
    status             text NOT NULL CHECK (status IN ('queued', 'running', 'succeeded', 'failed')),
    attempts           int NOT NULL DEFAULT 0,  -- LLM calls made, including the validation retry
    error              text NOT NULL DEFAULT '',
    strategy           text NOT NULL DEFAULT '', -- 'pdf-native' | 'text-extract'
    model              text NOT NULL DEFAULT '',
    input_tokens       int NOT NULL DEFAULT 0,
    output_tokens      int NOT NULL DEFAULT 0,
    thinking_tokens    int NOT NULL DEFAULT 0,
    total_tokens       int NOT NULL DEFAULT 0,
    extract_ms         bigint NOT NULL DEFAULT 0, -- local text extraction (text-extract only)
    llm_ms             bigint NOT NULL DEFAULT 0,
    total_ms           bigint NOT NULL DEFAULT 0,
    extracted_chars    int NOT NULL DEFAULT 0,
    validation_retries int NOT NULL DEFAULT 0,
    queued_at          timestamptz NOT NULL,
    started_at         timestamptz,
    finished_at        timestamptz
);
CREATE INDEX IF NOT EXISTS processing_jobs_owner_queued_idx ON processing_jobs (owner_id, queued_at DESC); -- daily upload limit
CREATE INDEX IF NOT EXISTS processing_jobs_chapter_idx ON processing_jobs (chapter_id, queued_at DESC);    -- latest job per chapter
-- Partial index: only unfinished jobs, scanned on boot to fail jobs interrupted by a restart.
CREATE INDEX IF NOT EXISTS processing_jobs_unfinished_idx ON processing_jobs (status) WHERE status IN ('queued', 'running');

-- A chapter's question bank. chapter_id UNIQUE enforces one set per chapter today;
-- dropping it later would allow versioned regeneration.
CREATE TABLE IF NOT EXISTS question_sets (
    id         uuid PRIMARY KEY,
    chapter_id uuid NOT NULL UNIQUE REFERENCES chapters (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL
);

-- Questions are immutable once saved: attempts reference them by ID, so editing one
-- would silently change past scores.
CREATE TABLE IF NOT EXISTS questions (
    id              uuid PRIMARY KEY,
    question_set_id uuid NOT NULL REFERENCES question_sets (id) ON DELETE CASCADE,
    position        int NOT NULL,               -- order within the set, 0-based
    -- domain.QuestionType: multiple choice, true/false, multiple response (select all that apply).
    type            text NOT NULL CHECK (type IN ('mcq', 'true_false', 'mrq')),
    prompt          text NOT NULL,
    -- Ordered list of option strings. jsonb rather than a child table: options are always
    -- read and written with their question and never queried on their own.
    options         jsonb NOT NULL,
    correct         int[] NOT NULL,             -- indices into options
    explanation     text NOT NULL,
    source_hint     text NOT NULL DEFAULT '',   -- where in the document the question came from
    UNIQUE (question_set_id, position)
);

-- One quiz run ("quiz" in the UI). question_ids snapshots the drawn questions in order,
-- so history shows exactly what was asked even though selection is random.
CREATE TABLE IF NOT EXISTS chapter_attempts (
    id              uuid PRIMARY KEY,
    owner_id        uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    chapter_id      uuid NOT NULL REFERENCES chapters (id) ON DELETE CASCADE,
    requested_count int NOT NULL,
    question_ids    uuid[] NOT NULL,
    -- domain.AttemptStatus: an attempt can be submitted once.
    status          text NOT NULL CHECK (status IN ('in_progress', 'submitted')),
    total_score     numeric(8, 4) NOT NULL DEFAULT 0, -- sum of per-question points (MRQ gives fractions)
    max_score       int NOT NULL,                     -- one point per question
    started_at      timestamptz NOT NULL,
    submitted_at    timestamptz
);
CREATE INDEX IF NOT EXISTS chapter_attempts_history_idx ON chapter_attempts (owner_id, chapter_id, started_at DESC);

-- Graded answers. A real table rather than jsonb on the attempt because question
-- selection asks "which questions has this user got wrong?" by question_id.
CREATE TABLE IF NOT EXISTS chapter_attempt_answers (
    attempt_id  uuid NOT NULL REFERENCES chapter_attempts (id) ON DELETE CASCADE,
    question_id uuid NOT NULL REFERENCES questions (id) ON DELETE CASCADE,
    position    int NOT NULL,
    selected    int[] NOT NULL,                 -- option indices the user picked
    points      numeric(5, 4) NOT NULL,         -- 0..1; MRQ partial credit
    correct     boolean NOT NULL,
    PRIMARY KEY (attempt_id, question_id)
);
CREATE INDEX IF NOT EXISTS chapter_attempt_answers_question_idx ON chapter_attempt_answers (question_id);

-- +goose Down
-- Drop in reverse dependency order. The citext extension is left installed because
-- other database objects may use it.
DROP TABLE IF EXISTS chapter_attempt_answers;
DROP TABLE IF EXISTS chapter_attempts;
DROP TABLE IF EXISTS questions;
DROP TABLE IF EXISTS question_sets;
DROP TABLE IF EXISTS processing_jobs;
DROP TABLE IF EXISTS chapters;
DROP TABLE IF EXISTS topics;
DROP TABLE IF EXISTS sessions;
DROP TABLE IF EXISTS oauth_accounts;
DROP TABLE IF EXISTS users;
